import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Targeting and assessment","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/combat/targeting.md","filePath":"game-design/combat/targeting.md"}'),i={name:"game-design/combat/targeting.md"};function o(s,e,l,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="targeting-and-assessment" tabindex="-1">Targeting and assessment <a class="header-anchor" href="#targeting-and-assessment" aria-label="Permalink to &quot;Targeting and assessment&quot;">​</a></h1><p><strong>Design status: Accepted direction and experimental resolver policy. Implementation: Stage 2A natural resolution integrated; aimed resolver remains pure and no player intent is stored.</strong></p><p>A player may prefer a body region while automatic combat continues. The server still decides whether a swing occurs, whether it hits and where it lands. Selection does not queue an extra attack, pause combat, reset recovery or guarantee a region.</p><h3 id="accepted-experimental-first-resolver" tabindex="-1">Accepted experimental first resolver <a class="header-anchor" href="#accepted-experimental-first-resolver" aria-label="Permalink to &quot;Accepted experimental first resolver&quot;">​</a></h3><p>The approved policy for later hit integration gives valid aim a <strong>50% placeholder</strong> chance to choose the intended region. Failure samples natural coverage <strong>excluding that entire intended region</strong>. Unrestricted fallback would inflate success to <code>p + (1-p) × naturalWeight</code>, so it is not the specified prototype. Natural/no-intent uses no aim roll. Aimed arm contact chooses Hands:Arms in a 1:2 ratio.</p><p>Revalidate the effective defender after redirection. Missing armor does not reroll location. Intent can survive a miss or brief loss of melee range, but Combatant/session/map/lifecycle changes invalidate context. A stale response must not clear a newer valid selection.</p><p>Assessment is planned to use existing gumps and explicit snapshots in Slice 0. Stage 2A now provides the <a href="/Syrolands-Public/game-design/skills-and-knowledge.html">approved qualitative Anatomy path</a>; native hotkeys remain separate work. <strong>Gap:</strong> no selection service, revision handling or live aiming has been implemented. Resolver checks do not establish live aiming or gameplay validation.</p><h2 id="proposed-targeting-factors-and-knowledge" tabindex="-1">Proposed targeting factors and knowledge <a class="header-anchor" href="#proposed-targeting-factors-and-knowledge" aria-label="Permalink to &quot;Proposed targeting factors and knowledge&quot;">​</a></h2><p>Batch 03 retains aiming as intent, never a guaranteed permanent region lock. Opportunities, position, attack execution, weapon, character skill, defender movement/defense, available information and stamina/fatigue are candidate influences. Their final accuracy/cost relationships remain Unresolved; they do not replace the accepted experimental resolver above.</p><p>Anatomy can support informed target choice through body-condition knowledge. <a href="/Syrolands-Public/game-design/skills-and-knowledge.html">Accepted disclosure</a> remains the boundary: the proposal grants no new hidden numerical information. Tactics and Arms Lore supply distinct opportunity/equipment roles. <a href="/Syrolands-Public/game-design/combat/stamina-and-reactive-combat.html">Stamina and reactive input</a> records the unresolved manual-input conflict without changing scheduled attacks.</p><p><a href="/Syrolands-Public/guide/combat/targeting-and-anatomy.html">Player guide: Targeted Attacks and Anatomy</a>.</p>',11)])])}const h=a(i,[["render",o]]);export{m as __pageData,h as default};
